"""
Benchmark script to analyze optimal chunk size for different numbers of processes.
Tests various combinations of chunk_size and num_processes to find optimal configuration.
"""

import time
import numpy as np
import multiprocessing as mp
import csv
import matplotlib.pyplot as plt
from matplotlib.colors import LogNorm
from itertools import product

from config import XMIN, XMAX, YMIN, YMAX, MAX_ITER, RESULT_DIR, RESOLUTION_RAMP_UP
from mp_implementation import compute_mandelbrot_parallel


def benchmark_chunk_process_combinations(
    resolution: int = 1024,
    chunk_sizes: list = None,
    process_counts: list = None,
    num_runs: int = 3
) -> list:
    """
    Benchmark different combinations of chunk sizes and process counts.
    
    Args:
        resolution: Image resolution (width=height)
        chunk_sizes: List of chunk sizes to test
        process_counts: List of process counts to test
        num_runs: Number of runs per configuration to average
    
    Returns:
        List of (chunk_size, num_processes, avg_time, std_time) tuples
    """
    max_cpus = mp.cpu_count()
    
    if chunk_sizes is None:
        # Test powers of 2 from 8 to 256
        chunk_sizes = [8, 16, 32, 64, 128, 256]
    
    if process_counts is None:
        # Test from 1 to max CPUs
        process_counts = list(range(1, max_cpus + 1))
    
    results = []
    total_configs = len(chunk_sizes) * len(process_counts)
    config_num = 0
    
    print(f"Benchmarking {total_configs} configurations at {resolution}x{resolution}")
    print(f"Chunk sizes: {chunk_sizes}")
    print(f"Process counts: {process_counts}")
    print(f"Runs per config: {num_runs}")
    print("=" * 60)
    
    for chunk_size, num_procs in product(chunk_sizes, process_counts):
        config_num += 1
        times = []
        
        # Skip invalid configurations
        if chunk_size > resolution:
            continue
        
        for run in range(num_runs):
            start = time.perf_counter()
            _ = compute_mandelbrot_parallel(
                XMIN, XMAX, YMIN, YMAX,
                resolution, resolution,
                chunk_size, chunk_size,
                num_processes=num_procs
            )
            elapsed = time.perf_counter() - start
            times.append(elapsed)
        
        avg_time = np.mean(times)
        std_time = np.std(times)
        
        results.append((chunk_size, num_procs, avg_time, std_time))
        print(f"[{config_num}/{total_configs}] chunk={chunk_size:3d}, P={num_procs:2d}: "
              f"{avg_time:.4f}s ± {std_time:.4f}s")
    
    return results


def save_results(results: list, filename: str):
    """Save benchmark results to CSV."""
    with open(filename, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['chunk_size', 'num_processes', 'avg_time', 'std_time'])
        writer.writerows(results)
    print(f"\nResults saved to {filename}")


def plot_results(results: list, resolution: int):
    """Create visualization of benchmark results."""
    # Convert to numpy for easier manipulation
    data = np.array(results)
    chunk_sizes = sorted(set(data[:, 0].astype(int)))
    process_counts = sorted(set(data[:, 1].astype(int)))
    
    # Create heatmap data
    heatmap = np.zeros((len(chunk_sizes), len(process_counts)))
    for chunk_size, num_procs, avg_time, _ in results:
        i = chunk_sizes.index(int(chunk_size))
        j = process_counts.index(int(num_procs))
        heatmap[i, j] = avg_time
    
    # Plot 1: Heatmap with logarithmic color scale
    fig, axes = plt.subplots(1, 2, figsize=(14, 5))
    
    # Use LogNorm for logarithmic color scaling to show small differences
    im = axes[0].imshow(heatmap, aspect='auto', cmap='viridis_r',
                        norm=LogNorm(vmin=heatmap.min(), vmax=heatmap.max()))
    axes[0].set_xticks(range(len(process_counts)))
    axes[0].set_xticklabels(process_counts)
    axes[0].set_yticks(range(len(chunk_sizes)))
    axes[0].set_yticklabels(chunk_sizes)
    axes[0].set_xlabel('Number of Processes (P)')
    axes[0].set_ylabel('Chunk Size')
    axes[0].set_title(f'Execution Time (log scale) - {resolution}x{resolution}')
    plt.colorbar(im, ax=axes[0], label='Time (s)')
    
    # Add text annotations (use geometric mean for log-scale threshold)
    log_threshold = np.sqrt(heatmap.min() * heatmap.max())
    for i in range(len(chunk_sizes)):
        for j in range(len(process_counts)):
            text = axes[0].text(j, i, f'{heatmap[i, j]:.2f}',
                               ha='center', va='center', fontsize=7,
                               color='white' if heatmap[i, j] > log_threshold else 'black')
    
    # Plot 2: Line plot for each chunk size
    for chunk_size in chunk_sizes:
        chunk_data = [(p, t) for cs, p, t, _ in results if int(cs) == chunk_size]
        chunk_data.sort()
        procs, times = zip(*chunk_data)
        axes[1].plot(procs, times, marker='o', label=f'chunk={chunk_size}')
    
    axes[1].set_xlabel('Number of Processes (P)')
    axes[1].set_ylabel('Execution Time (seconds)')
    axes[1].set_yscale('log')  # Log scale for y-axis to show small differences
    axes[1].set_title(f'Time vs Processes by Chunk Size - {resolution}x{resolution}')
    axes[1].legend()
    axes[1].grid(True, alpha=0.3, which='both')
    
    plt.tight_layout()
    plt.savefig(f'{RESULT_DIR}/chunk_benchmark_{resolution}.png', dpi=150)
    plt.show()
    
    # Find optimal configuration
    best = min(results, key=lambda x: x[2])
    print(f"\n{'='*60}")
    print(f"OPTIMAL CONFIGURATION for {resolution}x{resolution}:")
    print(f"  Chunk Size: {int(best[0])}")
    print(f"  Processes:  {int(best[1])}")
    print(f"  Time:       {best[2]:.4f}s ± {best[3]:.4f}s")
    print(f"{'='*60}")


if __name__ == "__main__":
    # Configuration
    RESOLUTION = RESOLUTION_RAMP_UP[4]  
    CHUNK_SIZES = [64, 128, 256, 512, 1024]  # Different chunk sizes to test
    PROCESS_COUNTS = [4,5,6,7,8,9,10]  # Different numbers of processes to test
    NUM_RUNS = 2  # Average over multiple runs for stability
    
    print(f"System has {mp.cpu_count()} CPU cores")
    print()
    
    # Run benchmark
    results = benchmark_chunk_process_combinations(
        resolution= RESOLUTION,
        chunk_sizes=CHUNK_SIZES,
        process_counts=PROCESS_COUNTS,
        num_runs=NUM_RUNS
    )
    
    # Save and visualize
    save_results(results, f'{RESULT_DIR}/chunk_benchmark_{RESOLUTION}.csv')
    plot_results(results, RESOLUTION)
